interface Lit { readonly type: "lit"; readonly value: number; readonly children: readonly Node[] }
interface Add { readonly type: "add"; readonly left: Node; readonly right: Node; readonly children: readonly Node[] }
type Node = Lit | Add;

function walk(n: Node, visit: (n: Node) => void): void {
  visit(n);
  for (const c of n.children) walk(c, visit);
}

function assertNever(x: never): never {
  throw new Error(`unhandled node: ${JSON.stringify(x)}`);
}
